def shift(text, amount):
    out = ''
    for ch in text:
        for alphabet in ['ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz','0123456789']:
            if ch in alphabet:
                out += alphabet[(alphabet.index(ch)+amount)%len(alphabet)]
                break
        else: out += ch
    return out
